ALTER TABLE invoices ADD COLUMN salesOrderId INT NULL AFTER goodsReceiptId;
ALTER TABLE invoices ADD COLUMN goodsIssueId INT NULL AFTER salesOrderId;
CREATE TABLE sales_orders (id INT AUTO_INCREMENT PRIMARY KEY, orderNo VARCHAR(80) NOT NULL UNIQUE, customerId INT NOT NULL, warehouseId INT NOT NULL, currencyCode VARCHAR(3) NOT NULL DEFAULT 'SAR', subtotal DECIMAL(20,6) NOT NULL DEFAULT 0, taxTotal DECIMAL(20,6) NOT NULL DEFAULT 0, grandTotal DECIMAL(20,6) NOT NULL DEFAULT 0, status ENUM('DRAFT','APPROVED','PARTIALLY_ISSUED','FULLY_ISSUED','CANCELLED') NOT NULL DEFAULT 'DRAFT', actor VARCHAR(100) NOT NULL, idempotencyKey VARCHAR(160) NOT NULL UNIQUE, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, approvedAt TIMESTAMP NULL, INDEX sales_order_customer_status_idx (customerId,status));
CREATE TABLE sales_order_lines (id INT AUTO_INCREMENT PRIMARY KEY, salesOrderId INT NOT NULL, itemId INT NOT NULL, quantity DECIMAL(20,6) NOT NULL, issuedQuantity DECIMAL(20,6) NOT NULL DEFAULT 0, unitPrice DECIMAL(20,6) NOT NULL, taxAmount DECIMAL(20,6) NOT NULL DEFAULT 0, lineTotal DECIMAL(20,6) NOT NULL);
CREATE TABLE goods_issues (id INT AUTO_INCREMENT PRIMARY KEY, issueNo VARCHAR(80) NOT NULL UNIQUE, salesOrderId INT NOT NULL, customerId INT NOT NULL, warehouseId INT NOT NULL, status ENUM('DRAFT','POSTED','CANCELLED') NOT NULL DEFAULT 'DRAFT', actor VARCHAR(100) NOT NULL, idempotencyKey VARCHAR(160) NOT NULL UNIQUE, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, postedAt TIMESTAMP NULL);
CREATE TABLE goods_issue_lines (id INT AUTO_INCREMENT PRIMARY KEY, goodsIssueId INT NOT NULL, salesOrderLineId INT NOT NULL, itemId INT NOT NULL, quantity DECIMAL(20,6) NOT NULL, unitCost DECIMAL(20,6) NOT NULL, serialsJson TEXT NULL);
